mapper.select:
/* mtgInqyDao1010 : 회의 목록 조회 */ SELECT M.MTG_ID , M.MTG_ID AS ID , M.MTG_TITLE AS TITLE , TO_CHAR(M.MTG_SDT, 'YYYY-MM-DD HH24:MI:SS') AS "START" , TO_CHAR(M.MTG_EDT, 'YYYY-MM-DD HH24:MI:SS') AS "END" , TO_CHAR(M.MTG_SDT, 'YYYY-MM-DD HH24:MI:SS') AS MTG_SDT , TO_CHAR(M.MTG_EDT, 'YYYY-MM-DD HH24:MI:SS') AS MTG_EDT , M.REG_IDX , E.EMP_NM , O.ORG_NM , R.RANK_NM , TO_CHAR(M.REG_DT, 'YYYYMMDD') AS REG_DT , M.MTG_LOC , C_LOC.CODE_NM AS MTG_LOC_NM FROM MEETING M LEFT OUTER JOIN EMP_INFO E ON M.REG_IDX = E.EMP_IDX LEFT OUTER JOIN ORG O ON O.ORG_CD = E.ORG_CD AND O.USE_YN = 'Y' LEFT OUTER JOIN RANK R ON R.RANK_CD = E.RANK_CD AND R.USE_YN = 'Y' LEFT OUTER JOIN CODE C_LOC ON C_LOC.CODE_CD = M.MTG_LOC WHERE M.USE_YN = 'Y'
AND REGEXP_REPLACE(LOWER(M.MTG_TITLE),'[^0-9가-힣A-Za-z]','') LIKE '%'||REGEXP_REPLACE(LOWER(#{srchNm, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]','')||'%'
AND REGEXP_REPLACE(LOWER(O.ORG_NM),'[^0-9가-힣A-Za-z]','') LIKE '%'||REGEXP_REPLACE(LOWER(#{orgNm, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]','')||'%'
AND REGEXP_REPLACE(LOWER(R.RANK_NM),'[^0-9가-힣A-Za-z]','') LIKE '%'||REGEXP_REPLACE(LOWER(#{rankNm, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]','')||'%'
AND M.MTG_LOC = #{srchLocCd, jdbcType=VARCHAR}

/* mtgInqyDao1030 : 회의 중복 조회 */ SELECT MTG_ID , TO_CHAR(MTG_SDT, 'HH24MI') AS MTG_STM , TO_CHAR(MTG_EDT, 'HH24MI') AS MTG_ETM FROM MEETING WHERE 1=1
AND MTG_ID != #{mtgId, jdbcType=VARCHAR}
AND MTG_SDT >= TO_DATE(#{mtgDt, jdbcType=VARCHAR}, 'YYYY-MM-DD') AND MTG_SDT < TO_DATE(#{mtgDt, jdbcType=VARCHAR}, 'YYYY-MM-DD') + 1
AND MTG_SDT >= TRUNC(SYSDATE) AND MTG_SDT < TRUNC(SYSDATE) + 1
AND MTG_LOC = #{mtgLoc, jdbcType=VARCHAR}
AND MTG_LOC = 'LOC_0010'

/* mtgInqyDao2020 : 캘린더 목록 조회 */ SELECT M.MTG_ID , M.MTG_TITLE , M.MTG_CONT , M.REG_IDX , TO_CHAR(M.MTG_SDT, 'YYYYMMDD') AS MTG_DT , E.EMP_NM , O.ORG_NM , R.RANK_NM , TO_CHAR(M.MTG_SDT, 'HH24MI') AS MTG_STM , TO_CHAR(M.MTG_EDT, 'HH24MI') AS MTG_ETM FROM MEETING M LEFT OUTER JOIN EMP_INFO E ON M.REG_IDX = E.EMP_IDX LEFT OUTER JOIN ORG O ON O.ORG_CD = E.ORG_CD LEFT OUTER JOIN RANK R ON R.RANK_CD = E.RANK_CD WHERE 1=1
AND M.MTG_SDT >= TO_DATE(REPLACE(#{mtgDt, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD') AND M.MTG_SDT < TO_DATE(REPLACE(#{mtgDt, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD') + 1
AND M.MTG_SDT >= TRUNC(SYSDATE) AND M.MTG_SDT < TRUNC(SYSDATE) + 1

mapper.update:
/* mtgProcDao1020 : 회의 삭제 처리 (수정)  */
DELETE FROM MEETING
	WHERE MTG_ID = #{mtgId, jdbcType=VARCHAR}

/* mtgProcDao1030 : 회의 수정 처리 */
UPDATE MEETING
	SET MTG_TITLE = #{mtgTitle, jdbcType=VARCHAR}
		,	MTG_CONT = #{mtgCont, jdbcType=VARCHAR}
		,	MTG_SDT = TO_DATE(#{mtgDt, jdbcType=VARCHAR} || ' ' || #{mtgStm, jdbcType=VARCHAR}, 'YYYY-MM-DD HH24:MI')
		,	MTG_EDT = TO_DATE(#{mtgDt, jdbcType=VARCHAR} || ' ' || #{mtgEtm, jdbcType=VARCHAR}, 'YYYY-MM-DD HH24:MI')
		,	MTG_LOC = #{mtgLoc, jdbcType=VARCHAR}
		,	MOD_IDX = #{modIdx, jdbcType=VARCHAR}
		,	MOD_DT = SYSDATE
WHERE MTG_ID = #{mtgId, jdbcType=VARCHAR}
